static ssize_t ina2xx_shunt_resistor_store ( struct device * dev , struct device_attribute * attr , const char * buf , size_t len ) { struct ina2xx_chip_info * chip = iio_priv ( dev_to_iio_dev ( dev ) ) ; unsigned long val ; int ret ; ret = kstrtoul ( ( const char * ) buf , 10 , & val ) ; ret = set_shunt_resistor ( chip , val ) ; if ( ret ) { return ret ; } ret = ina2xx_set_calibration ( chip ) ; if ( ret ) { return ret ; } return len ; } 